import json
from typing import Optional, Literal

from pyvkteamsclient.admin.base.client import BaseAdminClient
from pyvkteamsclient.tracer import tracer


class ChatsMethods(BaseAdminClient):
    @tracer.start_as_current_span("admin.chats.api_chats_search")
    def api_chats_search(
        self,
        filter_q: str,
        filter_group: bool = True,
        filter_channel: bool = True,
        filter_bot: bool = True,
        filter_public: bool = True,
        sort: list[str] = ("id", "DESC"),
        range_: list[int] = (0, 9),
    ):
        return self.get(
            path="api/chats/search",
            filter=json.dumps(
                {
                    "q": filter_q,
                    "type_group": filter_group,
                    "type_channel": filter_channel,
                    "type_bot": filter_bot,
                    "public": filter_public,
                },
            ),
            sort=json.dumps(sort),
            range=json.dumps(range_),
        )

    @tracer.start_as_current_span("admin.chats.api_chats_get_chat_id")
    def api_chats_get_chat_id(self, chat_id: str):
        return self.get(f"api/chats/get/{chat_id}")

    @tracer.start_as_current_span("admin.chats.api_chats_get_chat_id_members")
    def api_chats_get_chat_id_members(
        self,
        chat_id: str,
        filter_role: Literal["admin", "blocked", "member"] = "member",
        filter_page_size: int = 20,
        filter_name: Optional[str] = None,
        cursor: Optional[str] = None,
    ):
        return self.get(
            f"api/chats/get/{chat_id}/members",
            filter=json.dumps(
                {
                    "role": filter_role,
                    "page_size": filter_page_size,
                    "cursor": cursor,
                    "name": filter_name,
                },
            ),
        )

    @tracer.start_as_current_span("admin.chats.api_chats_update_member_role")
    def api_chats_update_member_role(
        self,
        chat_id: str,
        member_sn: str,
        role: Literal["admin", "blocked", "member"] = "member",
    ):
        return self.post(
            "api/chats/updateMemberRole",
            json={"chat_id": chat_id, "member_sn": member_sn, "role": role},
        )

    @tracer.start_as_current_span("admin.chats.post_api_chats_settings_ad")
    def post_api_chats_settings_ad(
        self,
        unit_id: str,
        unit_type: Literal["AD", "DI", "SYS"],
        chat_stamp: str,
        chat_name: str,
        admins: list[str],
    ):
        return self.post(
            "api/chats/settings/ad",
            json={
                "unit_id": unit_id,
                "unit_type": unit_type,
                "chat_stamp": chat_stamp,
                "chat_name": chat_name,
                "admins": admins,
            },
        )

    @tracer.start_as_current_span("admin.chats.get_api_chats_settings_ad")
    def get_api_chats_settings_ad(self, stamp: str, name: str):
        return self.get("api/chats/settings/ad", stamp=stamp, name=name)

    @tracer.start_as_current_span("admin.chats.get_api_chats_settings_ad_unit_id")
    def get_api_chats_settings_ad_unit_id(self, unit_id: str):
        return self.get(f"api/chats/settings/ad/{unit_id}")

    @tracer.start_as_current_span("admin.chats.delete_api_chats_settings_ad_unit_id")
    def delete_api_chats_settings_ad_unit_id(self, unit_id: str):
        return self.delete(f"api/chats/settings/ad/{unit_id}")
